import React, { useState } from 'react';

// Create your App component here
const App = () => {
  // Initialize userData state here
  const [userData, setUserData] = useState({ name: '', email: '' });

  // Define updateUserData handler here
  const updateUserData = () => {
    setUserData({ name: 'John Doe', email: 'john@example.com' });
  };

  // Define resetUserData handler here
  const resetUserData = () => {
    setUserData({ name: '', email: '' });
  };

  return (
    <div>
      {/* Add a section here to display current user data */}
      <div>
        <h3>Current User Data</h3>
        <p>Name: {userData.name}</p>
        <p>Email: {userData.email}</p>
      </div>
      <button onClick={updateUserData}>Update User</button>
      {/* Add reset button here */}
      <button onClick={resetUserData}>Reset User</button>

    </div>
  );
};

export default App;
